def choose_move(observation):
    # Defensive defaults
    # We interpret the observation as a generic grid-world state with optional keys.
    # We try to move towards a reasonable goal: avoid staying still if possible,
    # prefer moving in a consistent direction based on available information.

    # Helper to safely get values
    def get(o, k, default=None):
        if isinstance(o, dict):
            return o.get(k, default)
        return default

    # Try to infer a target direction from common fields
    dx = 0
    dy = 0

    # Prefer moving towards positive x (right) if a target is to the right
    target = get(observation, "target", None)
    if isinstance(target, (list, tuple)) and len(target) >= 2:
        # target format could be [tx, ty] or (tx, ty)
        tx, ty = target[0], target[1]
        # current position if available
        pos = get(observation, "position", None)
        if isinstance(pos, (list, tuple)) and len(pos) >= 2:
            x, y = pos[0], pos[1]
            dx = 1 if tx > x else -1 if tx < x else 0
            dy = 1 if ty > y else -1 if ty < y else 0

    # Fallback to other cues if target not present
    if dx == 0 and dy == 0:
        # Nearby agent or resource directions
        # Look for a resource to the right/left/up/down
        resources = get(observation, "resources", [])
        if isinstance(resources, list) and resources:
            # compute a simple vector toward the first resource
            r = resources[0]
            if isinstance(r, (list, tuple)) and len(r) >= 2:
                rx, ry = r[0], r[1]
                pos = get(observation, "position", None)
                if isinstance(pos, (list, tuple)) and len(pos) >= 2:
                    x, y = pos[0], pos[1]
                    dx = 1 if rx > x else -1 if rx < x else 0
                    dy = 1 if ry > y else -1 if ry < y else 0

    # If still no movement intent, move randomly between allowed directions deterministically
    if dx == 0 and dy == 0:
        # Use a deterministic pattern based on a hash of a stable field
        seed = 0
        stable = get(observation, "stable_id", None)
        if isinstance(stable, (int, float)):
            seed = int(stable)
        elif isinstance(stable, str):
            seed = sum(ord(c) for c in stable)

        choice = (seed % 4)
        if choice == 0:
            dx, dy = 1, 0
        elif choice == 1:
            dx, dy = -1, 0
        elif choice == 2:
            dx, dy = 0, 1
        else:
            dx, dy = 0, -1

    # Clip to -1, 0, 1 (defensive)
    if dx not in (-1, 0, 1):
        dx = 0
    if dy not in (-1, 0, 1):
        dy = 0

    return [dx, dy]

